import createClient from "openapi-fetch";
import type { paths } from "./schema";
import { ApiError, download, notifyUnauthorized, upload } from "./client";
import type {
  ApiKeyRecord,
  AuditRow,
  CommandBlock,
  ConfigSchema,
  FileEntry,
  HistoryRow,
  Overview,
  RecordingInfo,
  SessionInfo,
  ShareRecord,
  User,
} from "./types";

/**
 * The one HTTP client. Paths, query names and bodies are checked against the
 * OpenAPI document generated by ``scripts/export_openapi.py``; the hand-written
 * wrapper around ``fetch`` is gone. Response bodies from endpoints that return
 * ``dict[str, Any]`` are still cast at this boundary, but a typo in a path or a
 * renamed query parameter is now a TypeScript error instead of a 404 at runtime.
 */
const http = createClient<paths>({ baseUrl: "", credentials: "same-origin" });

type Result = Promise<{ data?: unknown; error?: unknown; response: Response }>;

function detailOf(error: unknown, response: Response): string {
  if (typeof error === "string" && error) return error;
  if (error && typeof error === "object" && "detail" in error) {
    const detail = (error as { detail?: unknown }).detail;
    if (typeof detail === "string") return detail;
    if (detail !== undefined) return JSON.stringify(detail);
  }
  return `${response.status} ${response.statusText}`;
}

async function unwrap<T>(request: Result): Promise<T> {
  const { data, error, response } = await request;
  if (response.status === 401) notifyUnauthorized();
  if (!response.ok || error !== undefined) {
    throw new ApiError(response.status, detailOf(error, response));
  }
  return data as T;
}

export const auth = {
  me: () => unwrap<User>(http.GET("/api/v2/me")),
  login: (username: string, password: string, totp?: string) =>
    unwrap<User>(
      http.POST("/api/v2/login", {
        body: { username, password, totp },
      }),
    ),
  logout: () => unwrap<{ ok: boolean }>(http.POST("/api/v2/logout")),
};

export const sessions = {
  list: () => unwrap<SessionInfo[]>(http.GET("/api/v2/sessions")),
  history: (limit = 50, cursor?: string) =>
    unwrap<HistoryRow[]>(
      http.GET("/api/v2/sessions/history", {
        params: { query: { limit, cursor } },
      }),
    ),
  create: (body: Record<string, unknown>) =>
    unwrap<SessionInfo>(
      http.POST("/api/v2/sessions", {
        body: body as never,
      }),
    ),
  remove: (sid: string) =>
    unwrap<{ ok: boolean }>(http.DELETE("/api/v2/sessions/{sid}", { params: { path: { sid } } })),
  rename: (sid: string, name: string) =>
    unwrap<{ ok: boolean }>(
      http.PATCH("/api/v2/sessions/{sid}", {
        params: { path: { sid } },
        body: { name },
      }),
    ),
  detail: (sid: string) =>
    unwrap<Record<string, unknown>>(
      http.GET("/api/v2/sessions/{sid}/detail", { params: { path: { sid } } }),
    ),
  reopen: (sid: string) =>
    unwrap<SessionInfo>(
      http.POST("/api/v2/sessions/{sid}/reopen", {
        params: { path: { sid } },
        body: {},
      }),
    ),
  commands: (sid: string, limit = 100) =>
    unwrap<{ commands: CommandBlock[] }>(
      http.GET("/api/v2/sessions/{sid}/commands", {
        params: { path: { sid }, query: { limit } },
      }),
    ),
};

export const files = {
  list: (path: string) =>
    unwrap<{
      entries: FileEntry[];
      path: string;
      root: string;
      total: number;
      offset: number;
      limit: number;
      truncated: boolean;
    }>(http.GET("/api/v2/files", { params: { query: { path } } })),
  read: async (path: string): Promise<string> => {
    const response = await fetch(`/api/v2/files/preview?path=${encodeURIComponent(path)}`, {
      credentials: "same-origin",
    });
    if (response.status === 401) notifyUnauthorized();
    if (!response.ok) {
      let detail = `HTTP ${response.status}`;
      try {
        detail = (await response.json()).detail ?? detail;
      } catch {
        /* ignore */
      }
      throw new ApiError(response.status, detail);
    }
    return response.text();
  },
  write: (path: string, content: string) =>
    unwrap<{ size: number }>(
      http.PUT("/api/v2/files/content", {
        body: { path, content },
      }),
    ),
  mkdir: (path: string, name: string) =>
    unwrap<{ name: string; path: string }>(
      http.POST("/api/v2/files/mkdir", {
        params: { query: { path } },
        body: { name },
      }),
    ),
  rename: (path: string, name: string) =>
    unwrap<{ name: string; path: string }>(
      http.POST("/api/v2/files/rename", {
        body: { path, name },
      }),
    ),
  remove: (path: string, name: string) =>
    unwrap<{ ok: boolean }>(
      http.DELETE("/api/v2/files", {
        params: { query: { path, name } },
      }),
    ),
  download: (path: string) => download(`/files/download?path=${encodeURIComponent(path)}`),
  url: (path: string) => `/api/v2/files/download?path=${encodeURIComponent(path)}`,
  imageUrl: (path: string) => `/api/v2/files/image?path=${encodeURIComponent(path)}`,
  upload: (
    path: string,
    file: File,
    overwrite = false,
    onProgress?: (ratio: number) => void,
    signal?: AbortSignal,
  ) => upload("/files/upload", file, { dir: path, overwrite, onProgress, signal }),
};

